sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    var infoPayload = JSON.parse(api.data.get_ops_user_data_1.output);
    api.setState('emailLogsSearchPayload', JSON.parse(infoPayload.emailLogs));
    var allEmailQueryURL = '/x/1324635/grc-operations-workspace/simplelist/sys_email/params/list-title/All%20Inbox/query/recipientsLIKE' + infoPayload.email.slice(0, -8) + '/disable-inline-editing/true';
    api.setState('viewAllEmailQuery', allEmailQueryURL);
    api.setState('birthAnniv', infoPayload.birthAnnivDue);
    api.setState('workAnniv', infoPayload.workAnnivDue);
    var allUserTaskURL = '/x/1324635/grc-operations-workspace/simplelist/x_1324635_grc_ops_user_tasks/params/list-title/All%20User%20Tasks/query/user=' + api.context.session.user.sys_id + '^ORDERBYsys_created_on' + '/disable-inline-editing/true';
    api.setState('allUserTasksURL', allUserTaskURL);
}
